/**
 * Dashboard Chart Renderer
 *
 * Handles all Chart.js rendering and chart instance management
 *
 * @package ContactInbox\Dashboard\JS
 */

const chartInstances = {};

const DashboardChartRenderer = {
    /**
     * Destroy a specific chart instance
     */
    destroyChart(chartName) {
        if (chartInstances[chartName]) {
            chartInstances[chartName].destroy();
            chartInstances[chartName] = null;
        }
    },

    /**
     * Render trend line chart
     */
    renderTrendChart(trendData) {
        const ctx = document.getElementById('chart-submissions-trend');
        if (!ctx) return;

        if (chartInstances.submissions) {
            chartInstances.submissions.destroy();
        }

        const labels = trendData.map((item) => item.date || 'N/A');
        const values = trendData.map((item) => item.count || 0);

        chartInstances.submissions = new Chart(ctx, {
            type: 'line',
            data: {
                labels,
                datasets: [
                    {
                        label: contactinAnalytics.i18n.submissions_tab || 'Submissions',
                        data: values,
                        borderColor: '#0073aa',
                        backgroundColor: 'rgba(0, 115, 170, 0.1)',
                        borderWidth: 2,
                        fill: true,
                        tension: 0.3,
                        pointRadius: 4,
                        pointHoverRadius: 6,
                        pointBackgroundColor: '#0073aa',
                        pointBorderColor: '#fff',
                        pointBorderWidth: 2,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false },
                },
                scales: {
                    y: {
                        beginAtZero: true,
                    },
                },
            },
        });
    },

    /**
     * Render device distribution pie chart
     */
    renderDeviceChart(deviceData) {
        const ctx = document.getElementById('chart-device-distribution');
        if (!ctx) return;

        if (chartInstances.device) {
            chartInstances.device.destroy();
        }

        const labels = Object.keys(deviceData);
        const values = Object.values(deviceData);
        const colors = ['#0073aa', '#82b536', '#ffb81c', '#d64545', '#7c3aed'];

        chartInstances.device = new Chart(ctx, {
            type: 'pie',
            data: {
                labels,
                datasets: [
                    {
                        data: values,
                        backgroundColor: colors.slice(0, labels.length),
                        borderColor: '#fff',
                        borderWidth: 2,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: { padding: 15, font: { size: 12 } },
                    },
                },
            },
        });
    },

    /**
     * Render geographic distribution bar chart
     */
    renderGeographicChart(geoData) {
        const ctx = document.getElementById('chart-geographic-distribution');
        if (!ctx) return;

        if (chartInstances.geographic) {
            chartInstances.geographic.destroy();
        }

        const labels = Object.keys(geoData);
        const values = Object.values(geoData);

        chartInstances.geographic = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [
                    {
                        label: 'Users',
                        data: values,
                        backgroundColor: '#0073aa',
                        borderColor: '#005a87',
                        borderWidth: 1,
                    },
                ],
            },
            options: {
                indexAxis: 'y',
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: { x: { beginAtZero: true } },
            },
        });
    },

    /**
     * Render traffic sources doughnut chart
     */
    renderSourcesChart(sourcesData) {
        const ctx = document.getElementById('chart-traffic-sources');
        if (!ctx) return;

        if (chartInstances.sources) {
            chartInstances.sources.destroy();
        }

        const labels = Object.keys(sourcesData);
        const values = Object.values(sourcesData);
        const colors = ['#0073aa', '#82b536', '#ffb81c', '#d64545', '#7c3aed', '#06b6d4'];

        chartInstances.sources = new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels,
                datasets: [
                    {
                        data: values,
                        backgroundColor: colors.slice(0, labels.length),
                        borderColor: '#fff',
                        borderWidth: 2,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: { padding: 15, font: { size: 12 } },
                    },
                },
            },
        });
    },

    /**
     * Render browser distribution bar chart
     */
    renderBrowserChart(browserData) {
        const ctx = document.getElementById('chart-browser-distribution');
        if (!ctx) return;

        if (chartInstances.browser) {
            chartInstances.browser.destroy();
        }

        const labels = Object.keys(browserData);
        const values = Object.values(browserData);

        chartInstances.browser = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [
                    {
                        label: 'Users',
                        data: values,
                        backgroundColor: '#82b536',
                        borderColor: '#5a8a25',
                        borderWidth: 1,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: { y: { beginAtZero: true } },
            },
        });
    },

    /**
     * Render CRM daily stats line chart
     */
    renderCRMDailyChart(dailyStats) {
        if (typeof Chart === 'undefined') {
            console.error('ContactIN CRM analytics: Chart.js not available');
            return;
        }
        
        const ctx = document.getElementById('chart-crm-daily-stats');
        
        if (!ctx) return;

        if (chartInstances['crm-daily']) {
            chartInstances['crm-daily'].destroy();
        }

        const labels = dailyStats.map((d) => d.date);
        const successData = dailyStats.map((d) => d.count || 0);
        const failedData = dailyStats.map((d) => d.failed || 0);

        try {
            chartInstances['crm-daily'] = new Chart(ctx, {
            type: 'line',
            data: {
                labels,
                datasets: [
                    {
                        label: 'Successful',
                        data: successData,
                        borderColor: '#10b981',
                        backgroundColor: 'rgba(16, 185, 129, 0.1)',
                        tension: 0.4,
                        fill: true,
                    },
                    {
                        label: 'Failed',
                        data: failedData,
                        borderColor: '#ef4444',
                        backgroundColor: 'rgba(239, 68, 68, 0.1)',
                        tension: 0.4,
                        fill: true,
                    },
                ],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { position: 'top' } },
                scales: {
                    y: { beginAtZero: true, ticks: { stepSize: 1 } },
                },
            },
            });
        } catch (e) {
            console.error('ContactIN CRM analytics: failed to render daily chart', e);
        }
    },
};
